page='''<!doctype html><meta charset="utf-8"><title>Veld original West idle source trials</title><style>body{background:#202a30;color:#eee;font:16px system-ui;margin:24px}.row{display:flex;gap:30px;align-items:end}img{width:256px}button{padding:8px;font:inherit}a{color:#b7daee}</style><h1>Veld original West idle source trials</h1><p>The first attempt adds an unwanted arm gesture and head movement. The blink-only retake is compared against the unchanged original master.</p><button onclick="setGear('bare')">Standard</button><button onclick="setGear('helmet')">Helmet</button><button onclick="setGear(gear)">Replay</button><div class="row"><figure><img id="original"><figcaption>Original master</figcaption></figure><figure><img id="first"><figcaption>First attempt — rejected motion</figcaption></figure><figure><img id="second"><figcaption>Blink-only retake — source review</figcaption></figure></div><p><a href="master-control-source-comparison.png">First source detail</a> · <a href="blink-only-v2/master-control-source-comparison.png">Retake detail</a></p><script>let gear='bare';function setGear(g){gear=g;document.querySelector('#original').src=g+'-original-reference.png';document.querySelector('#first').src=g+'-full-source.png?v='+Date.now();document.querySelector('#second').src='blink-only-v2/'+g+'-full-source.png?v='+Date.now()}setGear(gear)</script>'''
